INSERT INTO "users" ("id", "reputation", "creationdate", "displayname", "lastaccessdate", "websiteurl", "location", "aboutme", "views", "upvotes", "downvotes", "accountid", "age", "profileimageurl") VALUES (23, 308, '2010-07-19 19:09:16.0', 'Jay Stevens', '2014-08-11 19:51:32.0', 'http://www.centerlinescores.com', NULL, '<p>I design and build Grant and Program management web apps for SAIC by day and I design and build the best place to find US dressage scores  online for horse shows by night.  The first computers I programmed on were an IBM 8088 and an Apple 2.  I graduated in 1986 to a Mac-Plus... </p>

<blockquote>
  <p><em>(What''s the most powerful computer in the world?  The one people use.)</em></p>
</blockquote>

<p>... then I upgraded to dual floppy drives (Chuck Yeager Flight Simulator required it), then upgraded to a 40 MB HD (all my MIDI programming demanded it).  I was then seduced by the PC-dark side </p>

<blockquote>
  <p><em>(What''s the most powerful computer in the world?  The one that has software to run on it.)</em></p>
</blockquote>

<p>In 1990, I discovered SAS, SPSS and Statistics.  So while I''m a .NET geekarchitect today, I''m also a kick-butt SAS-Ninja-Shadow-Warrior as well.</p>
', 52, 34, 1, 21565, 46, NULL);
