INSERT INTO "comments" ("id", "postid", "score", "text", "creationdate", "userid", "userdisplayname") VALUES (273, 217, 1, 'That''s unfortunately one of Protovis''s weak points (but it''s an issue with any SVG library because IE doesn''t support that).  Fortunately, Jamie Love has come up with a solution using SVGWeb.  See here: http://groups.google.com/group/protovis/browse_thread/thread/1a80f98a16736658?pli=1.', '2010-07-21 13:37:53.0', 5, NULL);
