INSERT INTO "comments" ("id", "postid", "score", "text", "creationdate", "userid", "userdisplayname") VALUES (497, 244, 0, 'I tend to use some more than others- the tool I use most often for visualization is R and associated packages, but I left it off of this list because there is no easy way to compile R scripts to stand-alone "executables" that the OP wanted.  I can''t really claim a single favorite- I would have to say it depends on 1) The task at hand and 2) The tools I am using', '2010-07-25 20:26:16.0', 13, NULL);
INSERT INTO "comments" ("id", "postid", "score", "text", "creationdate", "userid", "userdisplayname") VALUES (589, 262, 3, '"Hardly publication quality"???? I realise that it isn''t perfect - the phrase "...should you get you started.." covers that bit. But with a little additional work, i.e. axis labels, I would say it''s fine. BTW, what journals do you publish in?', '2010-07-26 21:20:59.0', 8, NULL);
INSERT INTO "comments" ("id", "postid", "score", "text", "creationdate", "userid", "userdisplayname") VALUES (665, 47, 0, '@robin: thanks for comment. i haven''t seen much research in this area and the input from data provider was minimal [so far they were not interested/capable of investigating it further]. after initial exploration of data it was quite clear for me that there are couple of distinctive patterns [examples being ''heavy downloaders'' in just a few locations or ''frequent hoppers'' with lots of small sessions in large number of locations].
my goal at this stage was to try to use data itself to tell me how can i divide it best and minimize subjective input.', '2010-07-27 14:59:00.0', 22, NULL);
INSERT INTO "comments" ("id", "postid", "score", "text", "creationdate", "userid", "userdisplayname") VALUES (6347, 78, 0, '@neil-mcguigan: Opps. Thanks.', '2010-11-06 21:56:59.0', 8, NULL);
INSERT INTO "posthistory" ("id", "posthistorytypeid", "postid", "revisionguid", "creationdate", "userid", "text", "comment", "userdisplayname") VALUES (14, 2, 5, '5631dbb1-2781-4924-b7bd-5a67c06c5e4e', '2010-07-19 19:14:43.0', 23, 'The R-project\\n\\nhttp://www.r-project.org/', '', '');
INSERT INTO "posthistory" ("id", "posthistorytypeid", "postid", "revisionguid", "creationdate", "userid", "text", "comment", "userdisplayname") VALUES (15, 16, 5, '5631dbb1-2781-4924-b7bd-5a67c06c5e4e', '2010-07-19 19:14:43.0', -1, '', '', '');
INSERT INTO "posthistory" ("id", "posthistorytypeid", "postid", "revisionguid", "creationdate", "userid", "text", "comment", "userdisplayname") VALUES (39, 5, 5, 'd919c31f-f443-4bfa-9b5c-c306970ae92e', '2010-07-19 19:21:15.0', 23, 'The R-project\\n\\nhttp://www.r-project.org/\\n\\nR is valuable and significant because it was the first widely-accepted Open-Source alternative to big-box packages.  It''s mature, well supported, and a standard within many scientific communities.\\n\\n - [Some reasons why it is useful and valuable][1] \\n - There are some nice tutorials [here][2].\\n\\n\\n  [1]: http://www.inside-r.org/why-use-r\\n  [2]: http://gettinggeneticsdone.blogspot.com/search/label/ggplot2', 'add content from the comments;', '');
INSERT INTO "posthistory" ("id", "posthistorytypeid", "postid", "revisionguid", "creationdate", "userid", "text", "comment", "userdisplayname") VALUES (40, 2, 16, '7f07993b-9fa1-4359-8dec-f4e9aadfe8e2', '2010-07-19 19:22:31.0', 8, 'Two projects spring to mind:\\n\\n 1. [Bugs][1] - taking (some of) the pain out of Bayesian statistics. It allows the user to focus more on the model and a bit less on MCMC.\\n 1. [Bioconductor][2] - perhaps the most popular tool in Bioinformatics. I know it''s a R repository, but there are a large number of people who want to learn R, just for Bioconductor. The number of packages available for cutting edge analysis, make it second to none.\\n\\n\\n  [1]: http://www.mrc-bsu.cam.ac.uk/bugs/\\n  [2]: http://www.bioconductor.org/', '', '');
INSERT INTO "posthistory" ("id", "posthistorytypeid", "postid", "revisionguid", "creationdate", "userid", "text", "comment", "userdisplayname") VALUES (41, 16, 16, '7f07993b-9fa1-4359-8dec-f4e9aadfe8e2', '2010-07-19 19:22:31.0', -1, '', '', '');
INSERT INTO "posthistory" ("id", "posthistorytypeid", "postid", "revisionguid", "creationdate", "userid", "text", "comment", "userdisplayname") VALUES (107, 2, 47, '47eb2be3-688d-4b50-b187-047bfe45decd', '2010-07-19 19:36:12.0', 22, 'I have a dataset of 130k internet users characterized by 4 variables describing users'' number of sessions, locations visited, avg data download and session time aggregated from four months of activity.\\n\\nDataset is very heavy-tailed. For example third of users logged only once during four months, whereas six users had more than 1000 sessions.\\n\\nI wanted to come up with a simple classification of users, preferably with indication of the most appropriate number of clusters.\\n\\nIs there anything you could recomend as a soultion?\\n\\n', '', '');
INSERT INTO "posthistory" ("id", "posthistorytypeid", "postid", "revisionguid", "creationdate", "userid", "text", "comment", "userdisplayname") VALUES (108, 1, 47, '47eb2be3-688d-4b50-b187-047bfe45decd', '2010-07-19 19:36:12.0', 22, 'Clustering of large, heavy-tailed dataset  ', '', '');
INSERT INTO "posthistory" ("id", "posthistorytypeid", "postid", "revisionguid", "creationdate", "userid", "text", "comment", "userdisplayname") VALUES (109, 3, 47, '47eb2be3-688d-4b50-b187-047bfe45decd', '2010-07-19 19:36:12.0', 22, '<clustering>', '', '');
INSERT INTO "posthistory" ("id", "posthistorytypeid", "postid", "revisionguid", "creationdate", "userid", "text", "comment", "userdisplayname") VALUES (138, 2, 64, '3475f714-f1ed-4538-b78b-96c993f8dd34', '2010-07-19 19:46:08.0', 5, 'Yes, there are many methods.  You would need to specify which model you''re using, because it can vary.  \\n\\nFor instance, Some models will be compared based on the [AIC][1] or [BIC][2] criteria.  In other cases, one would look at the [MSE from cross validation][3] (as, for instance, with a support vector machine).\\n\\nI recommend reading [Pattern Recognition and Machine Learning][4] by Christopher Bishop.\\n\\n\\n  [1]: http://en.wikipedia.org/wiki/Akaike_information_criterion\\n  [2]: http://en.wikipedia.org/wiki/Bayesian_information_criterion\\n  [3]: http://en.wikipedia.org/wiki/Cross-validation_(statistics)\\n  [4]: http://research.microsoft.com/en-us/um/people/cmbishop/prml/', '', '');
INSERT INTO "posthistory" ("id", "posthistorytypeid", "postid", "revisionguid", "creationdate", "userid", "text", "comment", "userdisplayname") VALUES (139, 2, 65, 'e57bcbae-5a2f-4279-bd4c-cd728e4de6b8', '2010-07-19 19:46:11.0', 8, 'The first formula is the *population* standard deviation and the second formula is the the *sample* standard deviation. The second formula is also the unbiased maximum likelihood estimator of the standard deviation.\\n\\nI suppose (here) in the UK they don''t make the distinction between sample and population at high school. They certainly don''t touch concepts such as biased estimators. ', '', '');
INSERT INTO "posthistory" ("id", "posthistorytypeid", "postid", "revisionguid", "creationdate", "userid", "text", "comment", "userdisplayname") VALUES (145, 2, 70, 'ff76a5d4-d8ec-4a3b-9dbb-c2a3ba6cc68f', '2010-07-19 19:48:45.0', 22, '[World Bank][1] offers quite a lot of interesting data and has been recently very active in developing nice [API][2] for it.\\n\\n\\n  [1]: http://data.worldbank.org/data-catalog\\n  [2]: http://data.worldbank.org/developers/api-overview', '', '');
INSERT INTO "posthistory" ("id", "posthistorytypeid", "postid", "revisionguid", "creationdate", "userid", "text", "comment", "userdisplayname") VALUES (159, 2, 78, 'cf3824a4-3054-41b2-ae14-faa3ad0c9faf', '2010-07-19 19:54:38.0', 8, 'You tend to use the covariance matrix when the variable scales are similar and the correlation matrix when variables are on different scales. Using the covariance matrix *standardises* the data.\\n\\nIn general they give different results. Especially when the scales are different.', '', '');
INSERT INTO "posthistory" ("id", "posthistorytypeid", "postid", "revisionguid", "creationdate", "userid", "text", "comment", "userdisplayname") VALUES (172, 2, 86, '9bad9ae7-3b1f-4ec6-b275-69f71b0b6a98', '2010-07-19 20:08:37.0', 13, 'Unlike a normal variable, a random variable may not be substituted for a single, unchanging value.  Rather **statistical properties** such as the **distribution** of the random variable may be proscribed.  The distribution is a function that provides the probability the variable will take on a given value, or fall within a range given certain parameters such as the mean or standard deviation.  \\n\\nRandom variables may be classified as *discreet* if the distribution describes values from a countable set, such as the integers.  The other classification for a random variable is *continuous* and is used if the distribution covers values from an uncountable set such as the real numbers.', '', '');
INSERT INTO "posthistory" ("id", "posthistorytypeid", "postid", "revisionguid", "creationdate", "userid", "text", "comment", "userdisplayname") VALUES (176, 5, 64, 'c095b3e2-d112-4ee9-bab3-421f99d3bb25', '2010-07-19 20:12:16.0', 5, 'Yes, there are many methods.  You would need to specify which model you''re using, because it can vary.  \\n\\nFor instance, Some models will be compared based on the [AIC][1] or [BIC][2] criteria.  In other cases, one would look at the [MSE from cross validation][3] (as, for instance, with a support vector machine).\\n\\n 1. I recommend reading [Pattern Recognition and Machine Learning][4] by Christopher Bishop.\\n 2. This is also discussed in Chapter 5 on Credibility, and particularly section 5.5 "Comparing data mining methods" of [Data Mining: Practical Machine Learning Tools and Techniques][5] by Witten and Frank (which discusses Weka in detail).\\n 3. Lastly, you should also have a look at [The Elements of Statistical Learning][6] by Hastie, Tibshirani and Friedman which is available for free online.\\n\\n\\n  [1]: http://en.wikipedia.org/wiki/Akaike_information_criterion\\n  [2]: http://en.wikipedia.org/wiki/Bayesian_information_criterion\\n  [3]: http://en.wikipedia.org/wiki/Cross-validation_(statistics)\\n  [4]: http://research.microsoft.com/en-us/um/people/cmbishop/prml/\\n  [5]: http://www.amazon.com/Data-Mining-Practical-Techniques-Management/dp/0120884070/ref=ntt_at_ep_dpi_1\\n  [6]: http://www-stat.stanford.edu/~tibs/ElemStatLearn/', 'added 568 characters in body', '');
INSERT INTO "posthistory" ("id", "posthistorytypeid", "postid", "revisionguid", "creationdate", "userid", "text", "comment", "userdisplayname") VALUES (186, 5, 78, 'b9e34a27-912c-4ee1-b3d5-4afabeda9000', '2010-07-19 20:19:52.0', 8, 'You tend to use the covariance matrix when the variable scales are similar and the correlation matrix when variables are on different scales. Using the covariance matrix *standardises* the data.\\n\\nIn general they give different results. Especially when the scales are different.\\n\\nAs example, take a look a look at this R heptathlon data set. Some of the variables have an average value of about 1.8 (the high jump), whereas other variables (200m) are around 20.\\n\\n    library(HSAUR)\\n    # look at heptathlon data\\n    heptathlon\\n    \\n    # correlations\\n    round(cor(heptathlon[,-8]),2)   # ignoring "score" \\n    # covariance\\n    round(cov(heptathlon[,-8]),2)\\n    \\n    # PCA\\n    # scale=T bases the PCA on the correlation matrix\\n    hep.PC.cor = prcomp(heptathlon[,-8], scale=TRUE)\\n    hep.PC.cov = prcomp(heptathlon[,-8], scale=FALSE)\\n    \\n    # PC scores per competitor\\n    hep.scores.cor = predict(hep.PC.cor)\\n    hep.scores.cov = predict(hep.PC.cov)\\n    \\n    # Plot of PC1 vs PC2\\n    par(mfrow = c(2, 1))\\n    plot(hep.scores.cov[,1],hep.scores.cov[,2],\\n         xlab="PC 1",ylab="PC 2", pch=NA, main="Covariance")\\n    text(hep.scores.cov[,1],hep.scores.cov[,2],labels=1:25) \\n    \\n    plot(hep.scores.cor[,1],hep.scores.cor[,2],\\n         xlab="PC 1",ylab="PC 2", pch=NA, main="Correlation")\\n    text(hep.scores.cor[,1],hep.scores.cor[,2],labels=1:25) \\n\\n\\nNotice that the outlying individuals (in *this* data set) are outliers regardless of whether the covariance or correlation matrix is used.', 'Added R code', '');
INSERT INTO "posthistory" ("id", "posthistorytypeid", "postid", "revisionguid", "creationdate", "userid", "text", "comment", "userdisplayname") VALUES (202, 2, 102, 'abd65999-5783-4839-a1d8-c759970b1a8c', '2010-07-19 20:32:14.0', 22, 'For me [Illuminating the Path][1] report has been always good point of reference.   \\nFor more recent overview you can also have a look at good [article][2] by Heer and colleagues.\\n\\n\\n  [1]: http://nvac.pnl.gov/agenda.stm\\n  [2]: http://queue.acm.org/detail.cfm?id=1805128', '', '');
INSERT INTO "posthistory" ("id", "posthistorytypeid", "postid", "revisionguid", "creationdate", "userid", "text", "comment", "userdisplayname") VALUES (224, 5, 16, '6a7eb0c9-d732-4106-9d16-558372254714', '2010-07-19 20:43:02.0', 8, 'Two projects spring to mind:\\n\\n 1. [Bugs][1] - taking (some of) the pain out of Bayesian statistics. It allows the user to focus more on the model and a bit less on MCMC.\\n 1. [Bioconductor][2] - perhaps the most popular statistical tool in Bioinformatics. I know it''s a R repository, but there are a large number of people who want to learn R, just for Bioconductor. The number of packages available for cutting edge analysis, make it second to none.\\n\\n\\n  [1]: http://www.mrc-bsu.cam.ac.uk/bugs/\\n  [2]: http://www.bioconductor.org/', 'added 12 characters in body', '');
INSERT INTO "posthistory" ("id", "posthistorytypeid", "postid", "revisionguid", "creationdate", "userid", "text", "comment", "userdisplayname") VALUES (225, 5, 65, '116a8336-b0dc-47c5-890a-23cae0b14435', '2010-07-19 20:44:53.0', 8, 'The first formula is the *population* standard deviation and the second formula is the the *sample* standard deviation. The second formula is also related to the unbiased estimator of the variance - see [wikipedia][1] for further details.\\n\\nI suppose (here) in the UK they don''t make the distinction between sample and population at high school. They certainly don''t touch concepts such as biased estimators. \\n\\n\\n  [1]: http://en.wikipedia.org/wiki/Variance#Population_variance_and_sample_variance', 'Adding wikipedia link and changing sd to var', '');
INSERT INTO "posthistory" ("id", "posthistorytypeid", "postid", "revisionguid", "creationdate", "userid", "text", "comment", "userdisplayname") VALUES (271, 2, 129, '7b343dfd-2975-444d-8859-4f21c99f3499', '2010-07-19 21:24:58.0', 8, 'I quite like [Markov Chain Monte Carlo: Stochastic Simulation for Bayesian Inference][1] by Gamerman and Lopes.\\n\\nIt more an introduction to (advanced) Bayesian computation though.\\n\\n\\n  [1]: http://www.amazon.co.uk/o/ASIN/1584885874', '', '');
INSERT INTO "posthistory" ("id", "posthistorytypeid", "postid", "revisionguid", "creationdate", "userid", "text", "comment", "userdisplayname") VALUES (272, 16, 129, '7b343dfd-2975-444d-8859-4f21c99f3499', '2010-07-19 21:24:58.0', -1, '', '', '');
